# METADATA
# title: o6_17 Humuserhalt und Bodenschutz auf umbruchsfähigem Grünland – Basis
# description: >-
#   Gemeinsame Hilfsregeln, Vertragszeitraum, Kombinationsverpflichtung und
#   Zugangsvoraussetzungen (Merkblatt o6_17 Kap. 3-5, SRL 2.17, SRL 1.5.4, 1.7.1.2).
package oepul.o6_17

import rego.v1

tables := data.o6_17

year := input.farm.year

measure := object.get(input, ["farm", "oepul", "o6_17"], {})

parcels := object.get(input, ["land", "parcels"], [])

livestock_groups := object.get(input, ["livestock", "species_groups"], [])

field_use_types := {f.code: f | some f in tables.lists.field_use_types}

parcel_field_use(p) := object.get(p, ["oepul", "field_use_type"], "")

parcel_codes(p) := {c | some c in object.get(p, ["oepul", "codes"], [])}

parcel_measures(p) := {m | some m in object.get(p, ["oepul", "measures"], [])}

is_grassland(p) if p.land_use == "grassland"

# ---------------------------------------------------------------------------
# Vertragszeitraum (Merkblatt 3.1; Allg. Bedingungen 5.9; SRL 1.7.1.2)
# ---------------------------------------------------------------------------

contract_start_year := object.get(measure, "contract_start_year", null)

contract_period := period if {
	some period in tables.contract_periods.periods
	period.start_year == contract_start_year
}

# Letzter Einstieg mit Förderjahr 2025 (Merkblatt Kap. 7).
valid_entry_year if contract_period

contract_years := contract_period.years

contract_end := tables.contract_periods.contract_end

is_first_commitment_year if year == contract_start_year

in_contract_period if {
	contract_period
	year >= contract_start_year
	year <= 2028
}

# Maßnahmenantrag bis spätestens 31.12. vor Vertragsbeginn (Merkblatt Kap. 7).
application_deadline := sprintf("%d-12-31", [contract_start_year - 1]) if contract_period

application_timely if {
	submitted := measure.measure_application_date
	is_string(submitted)
	submitted <= application_deadline
}

# Vertragszeitraum des Zuschlags artenreiches Grünland: ein Kalenderjahr.
agl_contract_period := {
	"start": sprintf("%d-01-01", [year]),
	"end": sprintf("%d-12-31", [year]),
}

# ---------------------------------------------------------------------------
# Kombinationsverpflichtung (Merkblatt 3.2; SRL 2.17 Zugangsvoraussetzungen)
# ---------------------------------------------------------------------------

farm_measures := {m.measure_id | some m in object.get(input, ["farm", "oepul", "measures"], [])}

combination_requirement_met if {
	some required in tables.lists.combination_required_measures
	required.measure_id in farm_measures
}

# ---------------------------------------------------------------------------
# Mindestteilnahme (Merkblatt 3.3)
# ---------------------------------------------------------------------------

grassland_area_ha := object.get(input, ["land", "grassland_area_ha"], 0)

ln_without_alpine_ha := object.get(input, ["land", "total_area_ha"], 0) - object.get(input, ["land", "alpine_pasture_area_ha"], 0)

grassland_share := grassland_area_ha / ln_without_alpine_ha if ln_without_alpine_ha > 0

min_grassland_area_met if grassland_area_ha >= tables.thresholds.min_grassland_ha_first_year

grassland_share_met if grassland_share >= tables.thresholds.min_grassland_share_first_year

# ---------------------------------------------------------------------------
# Tierhaltender Betrieb (Merkblatt 3.4, 4, 11; SRL 1.5.4/1.5.5; Anhang A)
# ---------------------------------------------------------------------------

rgve_factor := {c.category_id: c.rgve_per_head |
	some c in tables.rgve_key.categories
	c.rgve_per_head != null
}

group_counts_for_rgve(g) if {
	rgve_factor[g.rgve_category]
	object.get(g, "kept_in_austria", true) == true
}

rgve_total := sum([(g.animal_count * rgve_factor[g.rgve_category]) |
	some g in livestock_groups
	group_counts_for_rgve(g)
])

non_feed_grassland(p) if field_use_types[parcel_field_use(p)].feed_area == false

is_feed_parcel(p) if {
	is_grassland(p)
	not non_feed_grassland(p)
}

is_feed_parcel(p) if {
	fu := field_use_types[parcel_field_use(p)]
	fu.land_use == "arable"
	fu.feed_area == true
}

feed_area_ha := sum([p.area_ha | some p in parcels; is_feed_parcel(p)])

livestock_density := rgve_total / feed_area_ha if feed_area_ha > 0

is_livestock_farm if livestock_density >= tables.thresholds.livestock_density_min_rgve_per_ha

# ---------------------------------------------------------------------------
# Zugangsvoraussetzungen und Folgen (SRL 2.17; SRL 1.12.1.1)
# ---------------------------------------------------------------------------

access_violations contains {
	"rule_id": "O617-ACC-COMBINATION",
	"message": "Keine zeitgleiche Teilnahme an UBB (o6_1a) oder BIO (o6_1b).",
} if {
	in_contract_period
	not combination_requirement_met
}

access_violations contains {
	"rule_id": "O617-ACC-MIN-GRASSLAND",
	"message": "Im ersten Teilnahmejahr werden weniger als 2,00 ha Grünland bewirtschaftet.",
} if {
	is_first_commitment_year
	not min_grassland_area_met
}

access_violations contains {
	"rule_id": "O617-ACC-GRASSLAND-SHARE",
	"message": "Im ersten Teilnahmejahr beträgt der Grünlandanteil weniger als 40 % der LN ohne Almweideflächen.",
} if {
	is_first_commitment_year
	not grassland_share_met
}

access_violations contains {
	"rule_id": "O617-ACC-LIVESTOCK",
	"message": "Im ersten Teilnahmejahr ist die Eigenschaft als tierhaltender Betrieb (>= 0,30 RGVE/ha Futterfläche) nicht erfüllt.",
} if {
	is_first_commitment_year
	not is_livestock_farm
}

access_violations contains {
	"rule_id": "O617-APP-LAST-ENTRY",
	"message": "Vertragsbeginn liegt außerhalb der zulässigen Einstiegsjahre 2023 bis 2025.",
} if {
	contract_start_year != null
	not valid_entry_year
}

access_violations contains {
	"rule_id": "O617-APP-DEADLINE",
	"message": "Maßnahmenantrag nicht bis 31.12. vor Vertragsbeginn gestellt.",
} if {
	contract_period
	is_string(object.get(measure, "measure_application_date", null))
	not application_timely
}

access_conditions_met if count(access_violations) == 0

# Nichterfüllung im 1. Jahr: kein Vertrag; ab dem 2. Jahr: keine Prämie im betroffenen Jahr.
contract_concluded if {
	valid_entry_year
	not first_year_access_failure
}

first_year_access_failure if {
	is_first_commitment_year
	count(access_violations) > 0
}

no_premium_due_to_access if {
	not is_first_commitment_year
	count(access_violations) > 0
}

# o6_17 – allgemeine ÖPUL-Teilnahmebedingungen
#
#   Förderwerbende Personen, Betriebsmindestgröße, Mindestbewirtschaftung,
#   Flächenabgang/-zugang, Maßnahmenübernahme, Sanktionsstufen, Auszahlung
#   (Allg. Teilnahmebedingungen 2026-04; SRL Allgemeiner Teil 1.4-1.12).
package oepul.o6_17

import rego.v1

general := tables.general_tables

applicant := object.get(input, ["farm", "applicant"], {})

oepul := object.get(input, ["farm", "oepul"], {})

# ---------------------------------------------------------------------------
# Förderwerbende Personen (Allg. 5.2; SRL 1.4)
# ---------------------------------------------------------------------------

applicant_types := {a.code: a | some a in tables.lists.applicant_types}

# o6_17 ist keine der Ausnahmemaßnahmen für Gebietskörperschaften.
o6_17_public_body_exception if {
	some m in tables.lists.public_body_exception_measures
	m.measure_id == "o6_17"
}

applicant_eligible if {
	t := applicant_types[applicant.legal_form]
	t.public_body_share_limited == false
	object.get(applicant, "is_active_farmer", false) == true
}

applicant_eligible if {
	t := applicant_types[applicant.legal_form]
	t.public_body_share_limited == true
	object.get(applicant, "public_body_share_percent", 0) <= tables.thresholds.public_body_max_share_percent
	object.get(applicant, "is_active_farmer", false) == true
}

# Gebietskörperschaften nur bei Ausnahmemaßnahmen (o6_17 ist keine solche).
applicant_eligible if {
	applicant.legal_form == "public_body"
	o6_17_public_body_exception
}

general_violations contains {
	"rule_id": "GEN-APPLICANT",
	"message": "Förderwerbende Person nicht teilnahmeberechtigt (Rechtsform, Beteiligung von Gebietskörperschaften > 25 % oder kein aktiver Landwirt).",
} if {
	applicant.legal_form
	not applicant_eligible
}

# ---------------------------------------------------------------------------
# Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr (Allg. 5.3; SRL 1.6.1)
# ---------------------------------------------------------------------------

is_first_oepul_year if year == object.get(oepul, "first_oepul_year", null)

farm_min_size_met if object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= tables.thresholds.farm_min_protected_cultivation_ha

farm_min_size_met if {
	total := object.get(input, ["land", "total_area_ha"], 0) + object.get(input, ["land", "protected_cultivation_area_ha"], 0)
	total >= tables.thresholds.farm_min_size_ha
}

general_violations contains {
	"rule_id": "GEN-FARM-MIN-SIZE",
	"message": "Betriebsmindestgröße im ersten ÖPUL-Jahr nicht erreicht (1,50 ha LN bzw. 0,50 ha geschützter Anbau).",
} if {
	is_first_oepul_year
	not farm_min_size_met
}

# ---------------------------------------------------------------------------
# Mindestbewirtschaftung auf Grünland- und Ackerfutterflächen (Allg. 5.4; SRL 1.6.3.3)
# ---------------------------------------------------------------------------

minimum_management_met(p) if parcel_field_use(p) in {"sonstige_gruenlandflaechen", "gruenlandbrache"}

minimum_management_met(p) if {
	parcel_field_use(p) != "bergmaehder"
	parcel_used_this_year(p)
}

minimum_management_met(p) if {
	parcel_field_use(p) == "bergmaehder"
	last := object.get(p, ["oepul", "last_mowing_year"], null)
	is_number(last)
	year - last < 2
}

general_violations contains {
	"rule_id": "GEN-MIN-MANAGEMENT-GRASSLAND",
	"parcel_id": p.parcel_id,
	"message": "Mindestbewirtschaftung nicht erfüllt (jährliche vollflächige Mahd mit Verbringung oder Beweidung; Bergmähder mind. alle 2 Jahre).",
} if {
	some p in parcels
	is_feed_parcel(p)
	not minimum_management_met(p)
}

# ---------------------------------------------------------------------------
# Flächenabgang während des Vertragszeitraums (Allg. 7.1; SRL 1.7.2.3)
# ---------------------------------------------------------------------------

tolerance := general.area_reduction_tolerance

area_reduction_tolerance_ha := max([
	min([tolerance.max_share * measure.measure_area_previous_year_ha, tolerance.max_ha]),
	tolerance.min_ha_always,
]) if {
	is_number(object.get(measure, "measure_area_previous_year_ha", null))
}

relevant_area_reduction_ha := max([
	0,
	((measure.measure_area_previous_year_ha - measure.measure_area_current_year_ha) - object.get(measure, "area_reduction_loss_of_disposal_ha", 0)) - object.get(measure, "area_reduction_permitted_conversion_ha", 0),
]) if {
	is_number(object.get(measure, "measure_area_previous_year_ha", null))
	is_number(object.get(measure, "measure_area_current_year_ha", null))
}

area_reduction_repayment_required if relevant_area_reduction_ha > area_reduction_tolerance_ha

# Rückzahlung für die gesamte Differenzfläche bei Überschreitung.
area_reduction_repayment_area_ha := relevant_area_reduction_ha if area_reduction_repayment_required

# ---------------------------------------------------------------------------
# Ausstieg vor Ende des Vertragszeitraums (Allg. 6; SRL 1.7.2, 1.10.5.3)
# ---------------------------------------------------------------------------

exit_year := object.get(measure, "exit_year", null)

early_exit_repayment_required if {
	is_number(exit_year)
	exit_year <= 2028
	object.get(measure, "exit_without_repayment_approved", false) == false
}

# ---------------------------------------------------------------------------
# Maßnahmenübernahme (Allg. 6.3; SRL 1.7.3.1)
# ---------------------------------------------------------------------------

takeover := object.get(measure, "takeover", {})

takeover_deadline(y) := sprintf("%d-%s", [y, tables.thresholds.takeover_deadline_2023_2028]) if y in {2023, 2028}

else := sprintf("%d-%s", [y, tables.thresholds.takeover_deadline])

takeover_permitted if {
	takeover.application_date <= takeover_deadline(year)
	object.get(takeover, "taker_previously_participating", false) == false
	takeover.expansion_to_other_area_ha <= tables.thresholds.takeover_max_expansion_share * takeover.taken_over_area_ha
}

# ---------------------------------------------------------------------------
# Sanktionen (Allg. 8.2; SRL 1.12.1.3)
# ---------------------------------------------------------------------------

sanction_share(stage, y) := s.reduction_share_until_2026 if {
	some s in general.sanction_stages
	s.stage == stage
	y < 2027
}

sanction_share(stage, y) := s.reduction_share_from_2027 if {
	some s in general.sanction_stages
	s.stage == stage
	y >= 2027
}

exclusion_required if object.get(measure, "full_reductions_in_contract_period", 0) >= 2

# ---------------------------------------------------------------------------
# Auszahlung (Allg. 9.1; SRL 1.10.7)
# ---------------------------------------------------------------------------

payment_deadline := sprintf("%d-%s", [year + 1, tables.thresholds.payment_deadline])

advance_payment_max_eur := premium_after_modulation_eur * tables.thresholds.advance_payment_max_share

payment_may_be_withheld if premium_after_modulation_eur <= tables.thresholds.payment_min_amount_eur

# o6_17 Förderverpflichtungen
#
#   Verzicht auf Grünlandumbruch, erlaubte Geräte, Ausnahmen, Weiterbildung,
#   Bodenuntersuchungen und Dokumentation artenreiches Grünland
#   (Merkblatt o6_17 Kap. 5, 6, 9; SRL 2.17; SRL Anhang H).
package oepul.o6_17

import rego.v1

thresholds := tables.thresholds

# ---------------------------------------------------------------------------
# Grünlandumbruch (Merkblatt 5.1, 6.1, 6.3; SRL 2.17)
# ---------------------------------------------------------------------------

minor_deviation_codes := {m.code | some m in tables.lists.minor_deviation_examples}

event_in_contract(e) if {
	contract_period
	e.event_date >= contract_period.contract_start
	e.event_date <= contract_period.contract_end
}

grassland_breaking_events contains {"parcel_id": p.parcel_id, "event": e} if {
	some p in parcels
	is_grassland(p)
	some e in object.get(p, ["oepul", "grassland_breaking_events"], [])
	event_in_contract(e)
}

# Ausnahme: Sanierung nach Schädlingsbefall, Notwendigkeit dokumentiert.
breaking_permitted(_, e) if {
	e.reason == "pest_damage_renovation"
	object.get(e, "documentation_kept", false) == true
}

# Ausnahme: Neueinsaat regionaler Saatgutmischung für Biodiversitätsflächen (UBB/BIO).
breaking_permitted(p, e) if {
	e.reason == "div_regional_seed_mixture"
	combination_requirement_met
	"DIVRS" in parcel_codes(p)
}

# Geringfügige Abweichungen bis 300 m² je Einzelfläche gelten nicht als Umbruch.
breaking_permitted(_, e) if {
	e.reason in minor_deviation_codes
	e.area_m2 <= thresholds.minor_deviation_max_m2
}

# Aufschüttungen > 300 m² nur mit vorab eingeholter landesrechtlicher Bewilligung.
breaking_permitted(_, e) if {
	e.reason == "fill_up"
	e.area_m2 > thresholds.minor_deviation_max_m2
	object.get(e, "state_permit_obtained", false) == true
}

parcel_by_id := {p.parcel_id: p | some p in parcels}

ploughing_violations contains {
	"rule_id": "O617-OBL-NO-PLOUGHING",
	"parcel_id": item.parcel_id,
	"event_date": item.event.event_date,
	"message": "Unzulässiger Grünlandumbruch während des Vertragszeitraums.",
} if {
	some item in grassland_breaking_events
	not breaking_permitted(parcel_by_id[item.parcel_id], item.event)
}

ploughing_violations contains {
	"rule_id": "O617-OBL-NO-SWAP",
	"parcel_id": null,
	"event_date": null,
	"message": "Acker-Grünland-Flächentausch ist nicht möglich.",
} if {
	in_contract_period
	object.get(measure, "arable_grassland_swap", false) == true
}

# Aufschüttung ohne Nutzung im betroffenen Jahr: Beantragung als "Sonstige Grünlandflächen".
parcel_used_this_year(p) if count(object.get(p, ["operations", "cutting_dates"], [])) > 0

parcel_used_this_year(p) if object.get(p, ["oepul", "grazed_fully"], false) == true

fill_up_declaration_violations contains {
	"rule_id": "O617-DEF-FILL-UP-UNUSED",
	"parcel_id": p.parcel_id,
	"message": "Aufschüttung ohne Nutzung im Jahr: Fläche ist als 'Sonstige Grünlandflächen' zu beantragen.",
} if {
	some p in parcels
	is_grassland(p)
	some e in object.get(p, ["oepul", "grassland_breaking_events"], [])
	e.reason == "fill_up"
	startswith(e.event_date, sprintf("%d-", [year]))
	not parcel_used_this_year(p)
	parcel_field_use(p) != "sonstige_gruenlandflaechen"
}

# ---------------------------------------------------------------------------
# Umbruchslose Grünlanderneuerung – zulässige Geräte (Merkblatt 6.2)
# ---------------------------------------------------------------------------

allowed_renewal_equipment := {e.id | some e in tables.lists.allowed_renewal_equipment}

renewal_equipment_violations contains {
	"rule_id": "O617-OBL-RENEWAL-EQUIPMENT",
	"parcel_id": p.parcel_id,
	"equipment": tool,
	"message": "Für die umbruchslose Grünlanderneuerung nicht zulässiges Gerät.",
} if {
	in_contract_period
	some p in parcels
	is_grassland(p)
	some tool in object.get(p, ["oepul", "renewal_equipment_used"], [])
	not tool in allowed_renewal_equipment
}

# ---------------------------------------------------------------------------
# Weiterbildung (Merkblatt 6.4; SRL 2.17)
# ---------------------------------------------------------------------------

training := object.get(measure, "training", {})

training_courses := object.get(training, "courses", [])

training_roles := {r.code | some r in tables.lists.training_attendee_roles}

attendee_left_before_deadline(c) if {
	left := object.get(c, "attendee_left_farm_date", null)
	is_string(left)
	left < thresholds.training_deadline
}

creditable_course(c) if {
	c.course_date >= thresholds.training_creditable_from
	c.course_date <= thresholds.training_deadline
	c.provider_recognized == true
	c.attendee_role in training_roles
	object.get(c, "credited_to_other_farm", false) == false
	object.get(c, "credited_to_other_commitment", false) == false
	not attendee_left_before_deadline(c)
}

training_hours := sum([c.hours | some c in training_courses; creditable_course(c)])

training_met if training_hours >= thresholds.training_min_hours

obligation_deadline_passed if year >= 2025

training_violations contains {
	"rule_id": "O617-OBL-TRAINING",
	"message": "Weiterbildung Grünlandbewirtschaftung im Mindestausmaß von 5 Stunden nicht bis 31.12.2025 absolviert.",
} if {
	in_contract_period
	obligation_deadline_passed
	not training_met
}

training_violations contains {
	"rule_id": "O617-OBL-TRAINING-CONFIRMATION",
	"message": "Kursbesuchsbestätigung trotz Aufforderung nicht an die AMA übermittelt.",
} if {
	object.get(training, "confirmation_requested", false) == true
	object.get(training, "confirmation_submitted", false) == false
	object.get(training, "transmitted_by_provider", false) == false
}

# ---------------------------------------------------------------------------
# Bodenuntersuchungen (Merkblatt 6.5; SRL 2.17)
# ---------------------------------------------------------------------------

gloez_ineligible_codes := {g.code | some g in tables.lists.gloez_conversion_bans_ineligible}

parcel_gloez_ineligible(p) if object.get(p, ["oepul", "gloez_conversion_ban"], "none") in gloez_ineligible_codes

# Ausgangsbasis: Grünland < 18 % gemäß MFA 2025 ohne GLÖZ 2/4/9-Flächen.
soil_sample_base_ha := max([0, measure.soil_sample_base_mfa2025_grassland_lt18_ha - object.get(measure, "soil_sample_base_gloez_excluded_ha", 0)]) if {
	is_number(object.get(measure, "soil_sample_base_mfa2025_grassland_lt18_ha", null))
}

# Ersatzweise Berechnung aus den Schlägen des Mehrfachantrags 2025.
soil_sample_base_ha := sum([p.area_ha |
	some p in parcels
	is_grassland(p)
	is_number(p.slope_percent)
	p.slope_percent < tables.premium_rates.base_slope_max_exclusive_percent
	not parcel_gloez_ineligible(p)
]) if {
	not is_number(object.get(measure, "soil_sample_base_mfa2025_grassland_lt18_ha", null))
	year == thresholds.soil_sample_reference_mfa_year
}

# Pro angefangene 5 ha mindestens eine Bodenprobe.
required_soil_samples := ceil(soil_sample_base_ha / thresholds.soil_sample_area_unit_ha)

required_soil_parameters := {s.code | some s in tables.lists.soil_sample_parameters}

soil_methods := {s.code | some s in tables.lists.soil_sample_methods}

creditable_soil_sample(s) if {
	s.sample_date >= thresholds.soil_sample_creditable_from
	s.lab_submission_date <= thresholds.soil_sample_deadline
	s.lab_accredited == true
	s.method in soil_methods
	every param in required_soil_parameters {
		param in s.parameters
	}
	object.get(s, "received_with_transferred_area", false) == false
}

soil_samples := object.get(measure, "soil_samples", [])

creditable_soil_sample_count := count([s | some s in soil_samples; creditable_soil_sample(s)])

soil_sampling_met if creditable_soil_sample_count >= required_soil_samples

soil_sampling_violations contains {
	"rule_id": "O617-OBL-SOIL-SAMPLES",
	"required": required_soil_samples,
	"creditable": creditable_soil_sample_count,
	"message": "Erforderliche Anzahl an Bodenproben nicht bis 31.12.2025 an ein akkreditiertes Labor übermittelt.",
} if {
	in_contract_period
	obligation_deadline_passed
	not soil_sampling_met
}

soil_sampling_violations contains {
	"rule_id": "O617-DOC-SOIL-RESULTS-GIS",
	"required": required_soil_samples,
	"creditable": creditable_soil_sample_count,
	"message": "Ergebnisse angerechneter Bodenproben nicht im INVEKOS-GIS erfasst.",
} if {
	some s in soil_samples
	creditable_soil_sample(s)
	object.get(s, "recorded_in_invekos_gis", false) == false
}

# ---------------------------------------------------------------------------
# Artenreiches Grünland – Kennarten und Dokumentation (Merkblatt 6.6, 9, 10; Anhang H)
# ---------------------------------------------------------------------------

kennarten_ids := {k.species_id | some k in tables.kennarten.species}

species_rich(p) := object.get(p, ["oepul", "species_rich"], {})

section_species_count(section) := count({sp |
	some sp in object.get(section, "indicator_species", [])
	sp in kennarten_ids
})

agl_species_requirement_met(p) if {
	sections := object.get(species_rich(p), "survey_sections", [])
	count(sections) > 0
	every section in sections {
		section_species_count(section) >= tables.kennarten.minimum_species_per_section
	}
}

agl_documentation_complete(p) if {
	object.get(species_rich(p), "survey_documented", false) == true
	object.get(species_rich(p), "sketch_documented", false) == true
	count(object.get(species_rich(p), "survey_dates", [])) >= 1
}

agl_first_use_mowing(p) if object.get(species_rich(p), "first_use_mowing", false) == true

agl_code_required(p) if field_use_types[parcel_field_use(p)].agl_mode == "code_agl_required"

agl_violations contains {
	"rule_id": "O617-AGL-SPECIES",
	"parcel_id": p.parcel_id,
	"message": "Als AGL beantragter Schlag: nicht in jedem Abschnitt mindestens 5 Kennarten.",
} if {
	some p in parcels
	"AGL" in parcel_codes(p)
	agl_code_required(p)
	not agl_species_requirement_met(p)
}

agl_violations contains {
	"rule_id": "O617-AGL-FIRST-USE-MOWING",
	"parcel_id": p.parcel_id,
	"message": "Als AGL beantragter Schlag: erste Nutzung nicht als Mahd.",
} if {
	some p in parcels
	"AGL" in parcel_codes(p)
	agl_code_required(p)
	not agl_first_use_mowing(p)
}

agl_violations contains {
	"rule_id": "O617-AGL-DOCUMENTATION",
	"parcel_id": p.parcel_id,
	"message": "Als AGL beantragter Schlag: Erhebung/Begehung, Erfassungsbogen oder Skizze nicht dokumentiert.",
} if {
	some p in parcels
	"AGL" in parcel_codes(p)
	agl_code_required(p)
	not agl_documentation_complete(p)
}

agl_violations contains {
	"rule_id": "O617-AGL-CODE-FIELD-USE",
	"parcel_id": p.parcel_id,
	"message": "Code AGL nur auf Mähwiese/-weide zwei bzw. drei und mehr Nutzungen.",
} if {
	some p in parcels
	"AGL" in parcel_codes(p)
	not agl_code_required(p)
}

